    PROC T9382dffx1()
        VAR jointtarget jtTG;
        tTG_Weld.tframe:=[[106.210,-1.030,520.250],[0.876727,0.000000,0.480989,0.000000]];
        tTG_Cam.tframe:=[[29.940,23.450,166.640],[0.491280,-0.492278,0.507015,0.509158]];
        wobjTG_Weld.uframe:=[[0,0,0],[1,0,0,0]];
        wobjTG_Weld.oframe:=[[0.000,0.000,0.000],[1.000000,0.000000,0.000000,0.000000]];
        wobjTG_Cam.uframe:=[[0,0,0],[1,0,0,0]];
        wobjTG_Cam.oframe:=[[0.000,0.000,0.000],[1.000000,0.000000,0.000000,0.000000]];
        wobjTG_WeldActStn.uframe:=[[0,0,0],[1,0,0,0]];
        wobjTG_WeldActStn.oframe:=[[-621.543,1290.355,797.596],[0.536457,-0.537943,0.460038,-0.459561]];
        TG_ActMechUnit;
        ConfL \Off;
        ConfJ \Off;
        stTG_ProgPass:="T9382dffx1";
        stTG_RobStatus:="Ok";
        stTG_SubName:="none";
        TG_ReqPassCheck \Tool:=tTG_Weld \WObj:=wobj0;
        IF nTG_PassOK<>1 THEN
        RETURN;
        ENDIF
        TG_DryRunOff;
        IF nTG_DryRun=1 TG_DryRunOn;
        ! Capture set Captures (0.0°)
        MoveAbsJ jtTG0001, vTG001, fine, tTG_Cam;
        MoveAbsJ jtTG0002, vTG001, fine, tTG_Cam;
        stTG_SubName:="C1PGlobal_0_1";
        TG_ReqCamFrame \Tool:=tTG_Cam \WObj:=wobjTG_Cam;
        IF nTG_DoCapture=2 GOTO abort_end;
        IF nTG_DoCapture=1 THEN
        TG_CamOpen;
        WaitTime 0.20;
        TG_ReqCapture \Tool:=tTG_Cam \WObj:=wobjTG_Cam;
        IF nTG_CaptureOK=0 GOTO abort_end;
        ENDIF
        MoveAbsJ jtTG0001, vTG001, fine, tTG_Cam;
        ! End of capture set
        TG_ReqGlobalCapDone;
        IF nTG_GlobalCapOK=0 GOTO abort_end;
        TG_CamClose;
        TG_WeldPrep;
        ! Transition
        jtTG := CJointT();
        jtTG.extax.eax_b := 0.000;
        jtTG.extax.eax_c := 6.857;
        MoveAbsJ jtTG, vmax, fine, tTG_Weld;
        MoveAbsJ jtTG0003, vmax, zTG001, tTG_Weld;
        MoveAbsJ jtTG0004, vmax, fine, tTG_Weld;
        ! Start of Weld1
        stTG_SubName:="PWeld1";
        TG_ReqWeldFrame \Tool:=tTG_Weld \WObj:=wobjTG_WeldActStn;
        TG_CamClose;
        IF nTG_WeldStatus=2 GOTO abort_end;
        IF nTG_WeldStatus=1 THEN
        IF Distance(CPos(\Tool:=tTG_Weld \WObj:=wobjTG_WeldActStn),pTG0001.trans)>100 THEN
        TPWrite "TG ERROR: weld frame check failed - torch far from chain entry";
        GOTO abort_end;
        ENDIF
        ConfL \On;
        MoveL pTG0001, vTG002, zTG001, tTG_Weld \WObj:=wobjTG_WeldActStn;
        MoveL pTG0002, vTG002, fine, tTG_Weld \WObj:=wobjTG_WeldActStn;
        TG_ReqWeldParams;
        TG_ApplyWeldParams 1;
        ArcLStart pTG0002, vTG002, sdTG_Weld, wdTG_Weld, fine, tTG_Weld \WObj:=wobjTG_WeldActStn;
        ArcL pTG0003, vTG002, sdTG_Weld, wdTG_Weld, zTG001, tTG_Weld \WObj:=wobjTG_WeldActStn;
        ArcL pTG0004, vTG002, sdTG_Weld, wdTG_Weld, zTG001, tTG_Weld \WObj:=wobjTG_WeldActStn;
        ArcL pTG0005, vTG002, sdTG_Weld, wdTG_Weld, zTG001, tTG_Weld \WObj:=wobjTG_WeldActStn;
        ArcLEnd pTG0006, vTG002, sdTG_Weld, wdTG_Weld, fine, tTG_Weld \WObj:=wobjTG_WeldActStn;
        ! process end
        MoveL pTG0007, vTG002, fine, tTG_Weld \WObj:=wobjTG_WeldActStn;
        ENDIF
        ! End of Weld1
        ! Transition
        MoveAbsJ jtTG0005, vmax, zTG001, tTG_Weld;
        MoveAbsJ jtTG0006, vmax, fine, tTG_Weld;
        jtTG := CJointT();
        jtTG.extax.eax_b := 0.000;
        jtTG.extax.eax_c := 0.000;
        MoveAbsJ jtTG, vmax, fine, tTG_Weld;
        MoveAbsJ jtTG0001, vmax, fine, tTG_Weld;
        ! Move to rest home
        TG_CamClose;
        TG_CamClose;
        abort_end:
        stTG_SubName:="none";
        TG_ReqEnd \Tool:=tTG_Weld \WObj:=wobj0;
    ENDPROC

